// Secure Node.js Application
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');

const app = express();

// Security Middleware
app.use(helmet({
  contentSecurityPolicy: process.env.CSP_ENABLED === 'true' ? undefined : false,
  crossOriginEmbedderPolicy: process.env.COEP_ENABLED === 'false' ? false : undefined,
  crossOriginOpenerPolicy: process.env.COOP_ENABLED === 'false' ? false : undefined,
  crossOriginResourcePolicy: process.env.CORP_ENABLED === 'false' ? false : undefined,
  dnsPrefetchControl: process.env.DNS_PREFETCH_CONTROL_ENABLED === 'false' ? false : undefined,
  expectCt: process.env.EXPECT_CT_ENABLED === 'false' ? false : undefined,
  frameguard: process.env.FRAMEGUARD_ENABLED === 'false' ? false : undefined,
  hidePoweredBy: process.env.HIDE_POWERED_BY_ENABLED === 'false' ? false : true,
  hsts: process.env.HSTS_ENABLED === 'false' ? false : { maxAge: process.env.HSTS_MAXAGE || 31536000, includeSubDomains: process.env.HSTS_INCLUDESUBDOMAINS === 'false' ? false : true },
  ieNoOpen: process.env.IE_NOOPEN_ENABLED === 'false' ? false : undefined,
  noSniff: process.env.NOSNIFF_ENABLED === 'false' ? false : undefined,
  originAgentCluster: process.originAgentCluster || (process.env.ORIGIN_AGENT_CLUSTER_ENABLED === 'false' ? false : undefined),
  permittedCrossDomainPolicies: process.env.PERMITTED_CROSS_DOMAIN_POLICIES_ENABLED === 'false' ? false : undefined,
  referrerPolicy: process.env.REFERRER_POLICY_ENABLED === 'false' ? false : { policy: process.env.REFERRER_POLICY || 'strict-origin-when-cross-origin' },
  xssFilter: process.env.XSS_FILTER_ENABLED === 'false' ? false : undefined,
}));
app.use(cors({
  origin: process.env.CORS_ORIGIN || true,
  methods: process.env.CORS_METHODS ? process.env.CORS_METHODS.split(',') : ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: process.env.CORS_ALLOWED_HEADERS ? process.env.CORS_ALLOWED_HEADERS.split(',') : ['Content-Type', 'Authorization'],
  credentials: process.env.CORS_CREDENTIALS === 'true',
}));
app.use(express.json({ 
  limit: process.env.BODY_LIMIT || '10kb' 
})); // Body parser with configurable size limit

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// Prevent parameter pollution
app.use(hpp());

// Rate limiting
const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000'), // Default 15 minutes
  max: parseInt(process.env.RATE_LIMIT_MAX || '100'), // Default 100 requests
  message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.',
  standardHeaders: process.env.RATE_LIMIT_STANDARD_HEADERS === 'true',
  legacyHeaders: process.env.RATE_LIMIT_LEGACY_HEADERS === 'false' ? false : true,
});
app.use(limiter);

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    service: process.env.SERVICE_NAME || 'nodejs-app',
    version: process.env.SERVICE_VERSION || '1.0.0'
  });
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  // In a real app, you'd validate and sanitize query parameters here
  // Example data - in production this would come from a database
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    success: false,
    message: process.env.NOT_FOUND_MESSAGE || 'Route not found',
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't leak stack trace in production
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    success: false,
    message: process.env.NODE_ENV === 'production' 
      ? (process.env.GENERIC_ERROR_MESSAGE || 'Something went wrong!') 
      : err.message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

