#!/usr/bin/env node
/*
 * Simple security audit script for Node.js applications
 * Checks for common security issues in the codebase
 */

const fs = require('fs');
const path = require('path');

console.log('🔍 Starting security audit...\n');

// Files to check
const filesToCheck = [
  'app.js',
  'app-secure.js',
  '.env.test',
  'package.json'
];

// Security issues to look for
const securityPatterns = [
  {
    pattern: /password\s*[:=]\s*['"][^"'"]+['"]/i,
    message: 'Hardcoded password detected',
    severity: 'HIGH'
  },
  {
    pattern: /api[_-]?key\s*[:=]\s*['"][^"'"]+['"]/i,
    message: 'Hardcoded API key detected',
    severity: 'HIGH'
  },
  {
    pattern: /secret\s*[:=]\s*['"][^"'"]+['"]/i,
    message: 'Hardcoded secret detected',
    severity: 'HIGH'
  },
  {
    pattern: /token\s*[:=]\s*['"][^"'"]+['"]/i,
    message: 'Hardcoded token detected',
    severity: 'HIGH'
  },
  {
    pattern: /aws[_-]?access[_-]?key[_-]?id\s*[:=]\s*['"][^"'"]+['"]/i,
    message: 'Hardcoded AWS credentials detected',
    severity: 'HIGH'
  },
  {
    pattern: /eval\s*\(/,
    message: 'Use of eval() detected - potential code injection',
    severity: 'HIGH'
  },
  {
    pattern: /new\s+Function\s*\(/,
    message: 'Use of Function constructor detected - potential code injection',
    severity: 'HIGH'
  },
  {
    pattern: /mongoose\s*=\s*require\(['"]mongoose['"]\)/,
    message: 'Mongoose usage detected - ensure schema validation is used',
    severity: 'MEDIUM',
    file: 'app.js'
  },
  {
    pattern: /express\(\)\s*;?\s*\n\s*app\.listen/,
    message: 'Express app without security middleware detected',
    severity: 'MEDIUM',
    file: 'app.js'
  }
];

let issuesFound = 0;

filesToCheck.forEach(file => {
  const filePath = path.join(__dirname, file);

  // Skip if file doesn't exist
  if (!fs.existsSync(filePath)) {
    return;
  }

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    securityPatterns.forEach(patternObj => {
      // Skip if this pattern is file-specific and doesn't match current file
      if (patternObj.file && patternObj.file !== file) {
        return;
      }

      const regex = patternObj.pattern;
      let match;

      // Check each line
      lines.forEach((line, lineIndex) => {
        while ((match = regex.exec(line)) !== null) {
          issuesFound++;
          console.log(`🚨 ${patternObj.severity} SECURITY ISSUE`);
          console.log(`   File: ${file}`);
          console.log(`   Line: ${lineIndex + 1}`);
          console.log(`   Message: ${patternObj.message}`);
          console.log(`   Content: ${line.trim()}\n`);

          // Continue searching for more matches in this line
          regex.lastIndex++;
        }
      });
    });

  } catch (error) {
    console.error(`❌ Error reading ${file}: ${error.message}`);
  }
});

// Check for missing security dependencies in package.json
const packageJsonPath = path.join(__dirname, 'package.json');
if (fs.existsSync(packageJsonPath)) {
  try {
    const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
    const dependencies = { ...packageJson.dependencies, ...packageJson.devDependencies };

    const securityDeps = ['helmet', 'express-rate-limit', 'cors'];
    const missingDeps = securityDeps.filter(dep => !dependencies[dep]);

    if (missingDeps.length > 0) {
      issuesFound += missingDeps.length;
      console.log(`⚠️  MEDIUM SECURITY ISSUE`);
      console.log(`   File: package.json`);
      console.log(`   Message: Missing security dependencies: ${missingDeps.join(', ')}`);
      console.log(`   Recommendation: Install these packages for basic security protection\n`);
    }

  } catch (error) {
    console.error(`❌ Error parsing package.json: ${error.message}`);
  }
}

console.log(`\n📊 Audit Complete: ${issuesFound} potential security issues found`);

if (issuesFound > 0) {
  console.log('\n🔧 Next Steps:');
  console.log('1. Review the issues identified above');
  console.log('2. Remove hardcoded secrets and use environment variables');
  console.log('3. Add security middleware (helmet, cors, rate limiting)');
  console.log('4. Implement proper input validation and sanitization');
  console.log('5. Use a .env file for configuration and add it to .gitignore');
  process.exit(1);
} else {
  console.log('\n✅ No obvious security issues detected!');
  process.exit(0);
}

