#!/usr/bin/env node
/*
 * Simple security check for obvious issues
 */

const fs = require('fs');
const path = require('path');

console.log('🔍 Running simple security check...\n');

const filesToCheck = [
  { file: 'app.js', description: 'Main application file' },
  { file: '.env.test', description: 'Test environment file' },
  { file: 'package.json', description: 'Package dependencies' }
];

let issuesFound = 0;

filesToCheck.forEach(({ file, description }) => {
  const filePath = path.join(__dirname, file);

  if (!fs.existsSync(filePath)) {
    console.log(`⚠️  File not found: ${file}`);
    return;
  }

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    console.log(`📄 Checking ${file} (${description})`);

    // Check for obvious security issues
    lines.forEach((line, lineIndex) => {
      const lineNum = lineIndex + 1;

      // Check for hardcoded secrets
      if (line.includes('password') && line.includes('=') && !line.includes('process.env')) {
        if (!line.startsWith('#') && !line.includes('//')) { // Not a comment
          console.log(`   🚨 Line ${lineNum}: Potential hardcoded password: ${line.trim()}`);
          issuesFound++;
        }
      }

      if (line.includes('api_key') || line.includes('apiKey')) {
        if (line.includes('=') && !line.includes('process.env') && !line.startsWith('#') && !line.includes('//')) {
          console.log(`   🚨 Line ${lineNum}: Potential hardcoded API key: ${line.trim()}`);
          issuesFound++;
        }
      }

      if (line.includes('secret') && line.includes('=')) {
        if (line.includes('=') && !line.includes('process.env') && !line.startsWith('#') && !line.includes('//')) {
          console.log(`   🚨 Line ${lineNum}: Potential hardcoded secret: ${line.trim()}`);
          issuesFound++;
        }
      }

      if (line.includes('token') && line.includes('=')) {
        if (line.includes('=') && !line.includes('process.env') && !line.startsWith('#') && !line.includes('//')) {
          console.log(`   🚨 Line ${lineNum}: Potential hardcoded token: ${line.trim()}`);
          issuesFound++;
        }
      }

      // Check for connection strings
      if (line.includes('postgres://') || line.includes('mongodb://') || line.includes('mysql://')) {
        if (line.includes('=') && !line.includes('process.env') && !line.startsWith('#') && !line.includes('//')) {
          console.log(`   🚨 Line ${lineNum}: Potential hardcoded database URL: ${line.trim()}`);
          issuesFound++;
        }
      }

      // Check for AWS keys
      if (line.includes('AKIA') || line.includes('AWS_ACCESS_KEY_ID') || line.includes('AWS_SECRET_ACCESS_KEY')) {
        if (line.includes('=') && !line.includes('process.env') && !line.startsWith('#') && !line.includes('//')) {
          console.log(`   🚨 Line ${lineNum}: Potential AWS credentials: ${line.trim()}`);
          issuesFound++;
        }
      }

      // Check for Stripe keys
      if (line.includes('sk_live') || line.includes('sk_test')) {
        if (line.includes('=') && !line.includes('process.env') && !line.startsWith('#') && !line.includes('//')) {
          console.log(`   🚨 Line ${lineNum}: Potential Stripe key: ${line.trim()}`);
          issuesFound++;
        }
      }
    });

    console.log(''); // Empty line for readability

  } catch (error) {
    console.error(`❌ Error reading ${file}: ${error.message}`);
  }
});

// Check package.json for missing security dependencies
const packageJsonPath = path.join(__dirname, 'package.json');
if (fs.existsSync(packageJsonPath)) {
  try {
    const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
    const dependencies = { ...packageJson.dependencies, ...packageJson.devDependencies || {} };

    console.log('📦 Checking package.json for security dependencies...');

    const securityDeps = ['helmet', 'express-rate-limit', 'cors'];
    const missingDeps = securityDeps.filter(dep => !(dependencies[dep] || '').trim());

    if (missingDeps.length > 0) {
      console.log(`   ⚠️  Missing security dependencies: ${missingDeps.join(', ')}`);
      issuesFound += missingDeps.length;
    } else {
      console.log(`   ✅ All security dependencies present`);
    }
    console.log('');

  } catch (error) {
    console.error(`❌ Error parsing package.json: ${error.message}`);
  }
}

console.log(`\n📊 Security Check Complete: ${issuesFound} potential issues found`);

if (issuesFound > 0) {
  console.log('\n🔧 Recommendations:');
  console.log('1. Move secrets to environment variables');
  console.log('2. Add .env file to .gitignore');
  console.log('3. Use helmet.js for security headers');
  console.log('4. Implement rate limiting');
  console.log('5. Use cors middleware appropriately');
  process.exit(1);
} else {
  console.log('\n✅ No obvious security issues detected!');
  process.exit(0);
}

#!/usr/bin/env node
/*
 * Check app.js specifically for security middleware
 */

const fs = require('fs');
const path = require('path');

console.log('🔍 Checking app.js for security middleware...\n');

const filePath = path.join(__dirname, 'app.js');
const secureFilePath = path.join(__dirname, 'app-secure.js');

function checkFile(filePath, description) {
  if (!fs.existsSync(filePath)) {
    console.log(`❌ ${description} not found: ${filePath}`);
    return [];
  }

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const issues = [];

    console.log(`📄 ${description}:`);

    // Check for security middleware
    if (!content.includes('helmet') && !content.includes('helmet(')) {
      issues.push('Missing helmet.js for security headers');
    }

    if (!content.includes('rateLimit') && !content.includes('express-rate-limit')) {
      issues.push('Missing rate limiting');
    }

    if (!content.includes('cors') && !content.includes('cors(')) {
      issues.push('Missing CORS middleware');
    }

    // Check for input validation
    if (!content.includes('validate') && !content.includes('sanitize')) {
      issues.push('No visible input validation/sanitization');
    }

    // Check for error handling
    if (!content.includes('next') || !content.includes('err')) {
      issues.push('Limited error handling visible');
    }

    if (issues.length > 0) {
      issues.forEach(issue => {
        console.log(`   ⚠️  ${issue}`);
      });
    } else {
      console.log(`   ✅ Basic security measures detected`);
    }

    console.log('');
    return issues;

  } catch (error) {
    console.error(`❌ Error reading ${filePath}: ${error.message}`);
    return [`Error reading file: ${error.message}`];
  }
}

const appIssues = checkFile(filePath, 'app.js');
const secureIssues = checkFile(secureFilePath, 'app-secure.js');

let totalIssues = appIssues.length + secureIssues.length;

console.log(`\n📊 Security Middleware Check:`);
console.log(`   app.js issues: ${appIssues.length}`);
console.log(`   app-secure.js issues: ${secureIssues.length}`);

if (totalIssues > 0) {
  console.log(`\n🔧 To fix issues in app.js:`);
  console.log(`   npm install helmet express-rate-limit cors`);
  console.log(`   Add security middleware to your Express app`);
  process.exit(1);
} else {
  console.log(`\n✅ Security middleware check passed!`);
  process.exit(0);
}

